  "test": "import pytest
from langfuse import observe


def test_observe_metadata_added_to_span(langfuse_memory_client, memory_exporter):
    @observe(name="metadata_span", metadata={"custom_key": "custom_val"})
    def dummy():
        return "ok"

    assert dummy() == "ok"

    # Ensure the span is exported
    langfuse_memory_client.flush()
    spans = [s for s in memory_exporter.get_finished_spans() if s.name == "metadata_span"]
    assert len(spans) == 1
    span = spans[0]
    # The custom metadata should appear as an attribute on the span
    assert span.attributes.get("custom_key") == "custom_val"
